 face orientation errors\n21:26 Note on face orientation\n22:05 Save As\n22:30 If you need thick and thin walls\n22:47 Great job!","commandRuns":[{"startIndex":19,"length":52,"onTap":{"innertubeCommand":{"clickTrackingParams":"CBIQ040EGAciEwiyjfjs26ySAxXNRT8BHcttNDnKAQThShN3","commandMetadata":{"webCommandMetadata":{"url":"/watch?v=0JdX11vu7Zo","webPageType":"WEB_PAGE_TYPE_WATCH","rootVe":3832}},"watchEndpoint":{"videoId":"0JdX11vu7Zo","startTimeSeconds":0,"watchEndpointSupportedOnesieConfig":{"html5PlaybackOnesieConfig":{"commonConfig":{"url":"https://rr4---sn-qxo7rn7y.googlevideo.com/initplayback?source=youtube\u0026oeis=1\u0026c=WEB\u0026oad=3200\u0026ovd=3200\u0026oaad=11000\u0026oavd=11000\u0026ocs=700\u0026oewis=1\u0026oputc=1\u0026ofpcc=1\u0026msp=1\u0026odepv=1\u0026id=d09757d75beeed9a\u0026ip=34.133.223.192\u0026mt=1769550775\u0026oweuc=\u0026pxtags=Cg4KAnR4Egg1MTUzOTgzMQ\u0026rxtags=Cg4KAnR4Egg1MTUzOTgzMA%2CCg4KAnR4Egg1MTUzOTgzMQ"}}}}}},"onTapOptions":{"accessibilityInfo":{"accessibilityLabel":"YouTube Channel Link: In-Depth Floor Plan Tutorial Part 2 [UPDATED 2025]"}}},{"startIndex":91,"length":52,"onTap":{"innertubeCommand":{"clickTrackingParams":"CBIQ040EGAciEwiyjfjs26ySAxXNRT8BHcttNDnKAQThShN3","commandMetadata":{"webCommandMetadata":{"url":"/watch?v=MEUsrN0V22g","webPageType":"WEB_PAGE_TYPE_WATCH","rootVe":3832}},"watchEndpoint":{"videoId":"MEUsrN0V22g","startTimeSeconds":0,"watchEndpointSupportedOnesieConfig":{"html5PlaybackOnesieConfig":{"commonConfig":{"url":"https://rr2---sn-qxo7rn7y.googlevideo.com/initplayback?source=youtube\u0026oeis=1\u0026c=WEB\u0026oad=3200\u0026ovd=3200\u0026oaad=11000\u0026oavd=11000\u0026ocs=700\u0026oewis=1\u0026oputc=1\u0026ofpcc=1\u0026msp=1\u0026odepv=1\u0026id=30452cacdd15db68\u0026ip=34.133.223.192\u0026mt=1769550775\u0026oweuc=\u0026pxtags=Cg4KAnR4Egg1MTUzOTgzMQ\u0026rxtags=Cg4KAnR4Egg1MTUzOTgzMA%2CCg4KAnR4Egg1MTUzOTgzMQ"}}}}}},"onTapOptions":{"accessibilityInfo":{"accessibilityLabel":"YouTube Channel Link: In-Dept